/* ─── TOKENS ─── */
:root {
    --bg: #08090b; --bg-1: #0b0c10; --bg-2: #0d0f13; --bg-3: #111319;
    --border: rgba(255, 255, 255, .08); --border-2: rgba(255, 255, 255, .13);
    --border-violet: rgba(155, 125, 255, .28);
    --violet: #7c5cff; --violet-bright: #9b7dff;
    --pink: #ff5da2; --amber: #ffb454;
    --grad: linear-gradient(120deg, #9b7dff 0%, #c084fc 45%, #ff5da2 100%);
    --grad-btn: linear-gradient(135deg, #8a63ff 0%, #b45cff 60%, #ff5da2 100%);
    --tx: #f5f5f7; --tx-2: #b7b7c2; --tx-3: #82828e; --tx-4: #4c4c56;
    --success: #4ade80; --danger: #f87171; --warning: #fb923c;
    --r-2xl: 28px; --r-xl: 22px; --r-lg: 16px; --r-md: 12px; --r-sm: 8px; --r-pill: 999px;
    --ease: all .22s cubic-bezier(.4, 0, .2, 1);
    --ease-spring: all .5s cubic-bezier(.16, 1, .3, 1);
    --nav-h: 72px;
    --font-display: 'Clash Display', 'Plus Jakarta Sans', sans-serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, monospace;
    --shadow-card: 0 1px 0 rgba(255, 255, 255, .03) inset, 0 10px 30px -12px rgba(0, 0, 0, .6);
    --shadow-glow: 0 0 0 1px rgba(124, 92, 255, .22), 0 12px 40px -8px rgba(124, 92, 255, .28);
    --ink: #04010f; --plum: #9b45ff; --plum-bright: #bf76ff;
    --rose: #e8399a; --amber-orange: #ff6d2e;
    --grad-nav: linear-gradient(135deg, #bf76ff 0%, #e8399a 52%, #ff6d2e 100%);
    --grad-btn-nav: linear-gradient(135deg, #9b45ff 0%, #e8399a 100%);
    --glass-bg: rgba(15, 6, 35, .45); --glass-border: rgba(191, 118, 255, .18);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; scroll-behavior: smooth; height: 100%; }
body {
    font-family: var(--font-body); background: var(--bg); color: var(--tx);
    min-height: 100vh; padding-top: calc(var(--nav-h) + 20px);
    -webkit-font-smoothing: antialiased; overflow-x: hidden;
}
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, .12); border-radius: 4px; }
:focus-visible { outline: 2px solid var(--violet-bright); outline-offset: 2px; border-radius: 4px; }

/* ─── BACKGROUND ─── */
.bg-canvas { position: fixed; inset: 0; z-index: 0; pointer-events: none; overflow: hidden; }
.bg-orb { position: absolute; border-radius: 50%; filter: blur(100px); opacity: .55; animation: orbFloat 26s ease-in-out infinite; }
.bg-orb-1 { width: 620px; height: 620px; top: -220px; left: -160px; background: radial-gradient(circle, rgba(124, 92, 255, .16) 0%, transparent 70%); }
.bg-orb-2 { width: 520px; height: 520px; top: 30%; right: -200px; background: radial-gradient(circle, rgba(255, 93, 162, .10) 0%, transparent 70%); animation-delay: -10s; }
.bg-grid {
    position: absolute; inset: 0;
    background-image: linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px),
                      linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px);
    background-size: 64px 64px;
    mask-image: radial-gradient(ellipse 80% 50% at 50% 0%, #000 40%, transparent 100%);
}
@keyframes orbFloat {
    0%, 100% { transform: translate(0, 0) scale(1); }
    50% { transform: translate(24px, 30px) scale(1.05); }
}

.skip-link { position: absolute; top: -9999px; left: 50%; transform: translateX(-50%); padding: 12px 22px; background: var(--violet); color: #fff; border-radius: var(--r-md); font-weight: 700; z-index: 9999; }
.skip-link:focus { top: 12px; }

/* ─── DYNAMIC ISLAND NAV ─── */
.dynamic-island {
    position: fixed; top: 12px; left: 50%; transform: translateX(-50%); z-index: 1000;
    width: auto; min-width: 280px; max-width: 92vw; height: 56px;
    background: rgba(8, 3, 22, .82); backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px);
    border-radius: var(--r-pill); border: 1px solid rgba(191, 118, 255, .12);
    box-shadow: 0 8px 32px rgba(0, 0, 0, .5); display: flex; align-items: center;
    padding: 0 6px; gap: 2px; transition: all .3s cubic-bezier(.34, 1.56, .64, 1);
}
.island-inner { display: flex; align-items: center; justify-content: space-between; width: 100%; height: 100%; padding: 0 4px; }
.island-brand { display: flex; align-items: center; gap: 8px; text-decoration: none; padding: 0 6px 0 4px; border-radius: var(--r-sm); transition: var(--ease); }
.island-brand:hover { background: rgba(155, 69, 255, .04); }
.island-brand-logo { width: 32px; height: 32px; border-radius: 4px; background: linear-gradient(135deg, rgba(155, 69, 255, .2), rgba(232, 57, 154, .12)); border: 1px solid rgba(155, 69, 255, .2); display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden; }
.island-brand-logo img { width: 18px; height: 18px; object-fit: contain; }
.island-brand-text {
    font-family: 'Clash Display', sans-serif; font-size: .92rem; font-weight: 700;
    background: var(--grad-nav); background-size: 200% 200%;
    -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
    animation: gradShift 6s ease infinite; white-space: nowrap;
}

.island-links { display: flex; align-items: center; gap: 1px; flex: 1; justify-content: center; padding: 0 4px; }
.island-link {
    display: flex; align-items: center; gap: 3px; padding: 5px 12px; border-radius: var(--r-sm);
    color: var(--tx-3); font-size: .75rem; font-weight: 600; background: none; border: none;
    cursor: pointer; transition: var(--ease); font-family: inherit; text-decoration: none; white-space: nowrap;
}
.island-link:hover { color: var(--tx-2); background: rgba(155, 69, 255, .06); }
.island-dropdown-wrap { position: relative; }
.island-dropdown {
    position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%) translateY(4px);
    min-width: 200px; background: rgba(8, 3, 22, .96); backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px); border: 1px solid rgba(155, 69, 255, .12);
    border-radius: var(--r-lg); padding: 6px 4px; box-shadow: 0 20px 60px rgba(0, 0, 0, .7);
    opacity: 0; pointer-events: none; transition: opacity .2s ease, transform .2s ease; z-index: 100;
}
.island-dropdown-wrap:hover .island-dropdown { opacity: 1; pointer-events: all; transform: translateX(-50%) translateY(0); }
.island-dropdown a, .island-dropdown .dd-item {
    display: flex; align-items: center; gap: 8px; padding: 6px 12px; border-radius: var(--r-sm);
    color: var(--tx-3); font-size: .73rem; font-weight: 500; text-decoration: none; transition: var(--ease);
    cursor: pointer; background: none; border: none; width: 100%; text-align: left; font-family: inherit;
}
.island-dropdown a:hover { background: rgba(155, 69, 255, .06); color: var(--tx-2); }
.island-dropdown .dd-icon { font-size: .9rem; }
.island-dropdown .dd-label { flex: 1; }
.island-dropdown .dd-divider { height: 1px; background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent); margin: 4px 8px; }
.island-right { display: flex; align-items: center; gap: 4px; flex-shrink: 0; padding-right: 2px; }
.island-btn {
    display: inline-flex; align-items: center; justify-content: center; gap: 4px;
    padding: 5px 14px; border-radius: var(--r-pill); border: none; cursor: pointer;
    font-family: inherit; font-size: .73rem; font-weight: 700; transition: var(--ease-spring);
    text-decoration: none; white-space: nowrap;
}
.island-btn-primary { background: var(--grad-btn-nav); color: #fff; box-shadow: 0 2px 12px rgba(155, 69, 255, .25); }
.island-btn-primary:hover { box-shadow: 0 4px 20px rgba(155, 69, 255, .35); transform: translateY(-1px); }
.island-btn-ghost { background: transparent; color: var(--tx-3); border: 1px solid rgba(255, 255, 255, .04); }
.island-btn-ghost:hover { background: rgba(255, 255, 255, .04); color: var(--tx-2); }
.island-btn-sm { padding: 4px 10px; font-size: .68rem; }
.island-avatar { width: 26px; height: 26px; border-radius: 50%; background: var(--grad-btn-nav); display: flex; align-items: center; justify-content: center; font-size: .65rem; font-weight: 800; color: #fff; flex-shrink: 0; }
.island-profile-email { font-size: .68rem; font-weight: 600; color: var(--tx-2); max-width: 80px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.island-hamburger { display: none; flex-direction: column; gap: 3px; padding: 6px 8px; background: none; border: none; cursor: pointer; color: var(--tx); border-radius: var(--r-sm); }
.island-hamburger span { display: block; width: 18px; height: 1.5px; background: currentColor; border-radius: 1px; transition: transform .28s, opacity .2s; }
.island-hamburger.open span:nth-child(1) { transform: translateY(4.5px) rotate(45deg); }
.island-hamburger.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.island-hamburger.open span:nth-child(3) { transform: translateY(-4.5px) rotate(-45deg); }

.island-mobile-overlay {
    display: none; position: fixed; inset: 0; z-index: 999;
    background: rgba(4, 1, 15, .92); backdrop-filter: blur(32px) saturate(160%);
    padding: 80px 20px 32px; overflow-y: auto; flex-direction: column; gap: 2px;
}
.island-mobile-overlay.open { display: flex; }
.island-mobile-overlay .mob-section { padding: 8px 0 2px 12px; font-size: .55rem; text-transform: uppercase; letter-spacing: .12em; color: var(--tx-4); font-weight: 800; margin-top: 4px; }
.island-mobile-overlay .mob-link {
    display: flex; align-items: center; gap: 12px; padding: 10px 14px;
    border-radius: var(--r-md); color: var(--tx-3); font-size: .85rem; font-weight: 600;
    text-decoration: none; border: none; background: none; width: 100%; text-align: left;
    font-family: inherit; cursor: pointer;
}
.island-mobile-overlay .mob-link:hover { background: rgba(155, 69, 255, .05); color: var(--tx-2); }
.island-mobile-overlay .mob-link .mob-icon { font-size: 1rem; }
.island-mobile-overlay .mob-divider { height: 1px; background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent); margin: 4px 12px; }
.island-overlay-close { position: fixed; top: 16px; right: 20px; z-index: 1001; width: 40px; height: 40px; border-radius: 50%; background: rgba(155, 69, 255, .06); border: 1px solid rgba(155, 69, 255, .12); color: var(--tx-3); font-size: 1.2rem; cursor: pointer; display: none; align-items: center; justify-content: center; }
.island-overlay-close.visible { display: flex; }
@keyframes gradShift {
    0%, 100% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
}

@media (max-width:1024px) {
    .dynamic-island { min-width: 200px; height: 50px; top: 10px; }
    .island-brand-text { font-size: .8rem; }

    .island-link { font-size: .7rem; padding: 4px 8px; }
    .island-btn { font-size: .68rem; padding: 4px 10px; }
    .island-profile-email { max-width: 60px; font-size: .62rem; }
}
@media (max-width:820px) {
    .island-links { display: none; }
    .island-hamburger { display: flex; }
    .dynamic-island { min-width: 140px; height: 44px; top: 8px; padding: 0 4px; }
    .island-brand-text { font-size: .72rem; }
    body { padding-top: 64px; }
}
@media (max-width:480px) {
    .dynamic-island { min-width: 100px; height: 40px; top: 6px; }
    .island-brand-text { font-size: .65rem; }
    .island-right .island-btn-primary { padding: 2px 8px; font-size: .55rem; }
    body { padding-top: 56px; }
}

/* ─── BUTTONS ─── */
.btn {
    display: inline-flex; align-items: center; justify-content: center; gap: 6px;
    padding: 8px 18px; border-radius: var(--r-md); border: none; cursor: pointer;
    font-family: inherit; font-size: .8rem; font-weight: 700; transition: var(--ease-spring);
    text-decoration: none; white-space: nowrap; position: relative; overflow: hidden;
}
.btn:disabled { opacity: .55; cursor: not-allowed; transform: none !important; }
.btn-primary { background: var(--grad-btn); color: #fff; box-shadow: 0 4px 20px rgba(155, 69, 255, .35); }
.btn-primary:hover:not(:disabled) { box-shadow: 0 8px 32px rgba(155, 69, 255, .5); transform: translateY(-1px); }
.btn-secondary { background: rgba(155, 69, 255, .08); color: var(--violet-bright); border: 1px solid rgba(155, 69, 255, .18); }
.btn-secondary:hover:not(:disabled) { background: rgba(155, 69, 255, .16); transform: translateY(-1px); }
.btn-danger { background: rgba(232, 57, 154, .15); color: var(--rose); border: 1px solid rgba(232, 57, 154, .2); }
.btn-danger:hover:not(:disabled) { background: rgba(232, 57, 154, .25); transform: translateY(-1px); }
.btn-warning { background: rgba(255, 109, 46, .12); color: #ff7a3d; border: 1px solid rgba(255, 109, 46, .18); }
.btn-warning:hover:not(:disabled) { background: rgba(255, 109, 46, .22); transform: translateY(-1px); }
.btn-success { background: rgba(74, 222, 128, .1); color: var(--success); border: 1px solid rgba(74, 222, 128, .15); }
.btn-success:hover:not(:disabled) { background: rgba(74, 222, 128, .18); transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--tx-3); border: 1px solid var(--border-2); }
.btn-ghost:hover:not(:disabled) { background: rgba(255, 255, 255, .04); color: var(--tx-2); }
.btn-sm { padding: 4px 12px; font-size: .72rem; }
.btn-full { width: 100%; }
.btn .spinner {
    display: inline-block; width: 12px; height: 12px; border-radius: 50%;
    border: 2px solid rgba(255, 255, 255, .3); border-top-color: #fff;
    animation: spin .6s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.main-wrap { max-width: 1440px; margin: 0 auto; padding: 0 28px 60px; position: relative; z-index: 1; }

/* ─── ADMIN HEADER ─── */
.admin-header {
    display: flex; justify-content: space-between; align-items: center;
    padding: 20px 28px; background: var(--bg-1); border: 1px solid var(--border);
    border-radius: var(--r-xl); margin-bottom: 28px; flex-wrap: wrap; gap: 16px;
}
.admin-header-left { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.admin-title {
    font-family: var(--font-display); font-size: 1.4rem; font-weight: 700;
    background: var(--grad); -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text; display: flex; align-items: center; gap: 10px;
}
.back-home-btn {
    padding: 6px 14px; border-radius: var(--r-pill); background: rgba(155, 69, 255, .08);
    border: 1px solid rgba(155, 69, 255, .15); color: var(--violet-bright);
    font-size: .72rem; font-weight: 600; text-decoration: none; transition: var(--ease);
    display: inline-flex; align-items: center; gap: 4px;
}
.back-home-btn:hover { background: rgba(155, 69, 255, .15); transform: translateX(-2px); }
.admin-stats-bar { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.stat-pill {
    text-align: center; padding: 6px 16px; background: rgba(155, 69, 255, .06);
    border: 1px solid rgba(155, 69, 255, .1); border-radius: var(--r-lg); min-width: 72px;
    transition: var(--ease);
}
.stat-pill:hover { border-color: rgba(155, 69, 255, .25); background: rgba(155, 69, 255, .1); }
.stat-pill .num { font-family: var(--font-display); font-size: 1.2rem; font-weight: 700; color: var(--violet-bright); }
.stat-pill .label { font-size: .6rem; text-transform: uppercase; letter-spacing: .06em; color: var(--tx-4); font-weight: 700; }
.admin-user { display: flex; align-items: center; gap: 12px; }
.admin-avatar {
    width: 40px; height: 40px; border-radius: 50%; background: var(--grad-btn-nav);
    display: flex; align-items: center; justify-content: center; font-weight: 800;
    font-size: 1rem; color: #fff; flex-shrink: 0; box-shadow: 0 0 12px rgba(155, 69, 255, .2);
}
.admin-user-info .admin-email { font-weight: 600; font-size: .85rem; color: var(--tx); }
.admin-user-info .admin-role { font-size: .65rem; color: var(--tx-4); font-weight: 600; text-transform: uppercase; letter-spacing: .06em; }

/* ─── STATS GRID ─── */
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 28px; }
.stat-card {
    padding: 20px 22px; background: var(--bg-1); border: 1px solid var(--border);
    border-radius: var(--r-xl); transition: var(--ease); cursor: pointer; position: relative; overflow: hidden;
}
.stat-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
    background: var(--grad); opacity: 0; transition: opacity .3s;
}
.stat-card:hover { border-color: var(--border-violet); transform: translateY(-3px); box-shadow: var(--shadow-card); }
.stat-card:hover::before { opacity: 1; }
.stat-card .stat-value {
    font-family: var(--font-display); font-size: 2rem; font-weight: 700;
    background: var(--grad); -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text; line-height: 1.2; display: flex; align-items: baseline; gap: 8px;
}
.stat-card .stat-label { font-size: .78rem; color: var(--tx-3); margin-top: 4px; font-weight: 500; }
.stat-card .stat-icon { font-size: 1.2rem; -webkit-text-fill-color: initial; }
.stat-trend {
    display: inline-flex; align-items: center; gap: 2px; padding: 1px 8px;
    border-radius: var(--r-pill); font-size: .65rem; font-weight: 700; letter-spacing: .02em;
}
.stat-trend.up { background: rgba(74, 222, 128, .1); color: var(--success); }
.stat-trend.down { background: rgba(248, 113, 113, .1); color: var(--danger); }
.stat-trend.neutral { background: rgba(155, 125, 255, .1); color: var(--violet-bright); }

/* ─── TAB BAR ─── */
.tab-bar {
    display: flex; gap: 4px; margin-bottom: 24px; border-bottom: 1px solid var(--border);
    padding-bottom: 12px; flex-wrap: wrap;
}
.tab-btn {
    padding: 10px 20px; background: transparent; border: none; color: var(--tx-3);
    font-family: var(--font-body); font-weight: 600; font-size: .82rem; cursor: pointer;
    transition: var(--ease); border-radius: var(--r-md); display: flex; align-items: center; gap: 6px;
    position: relative;
}
.tab-btn:hover { color: var(--tx-2); background: rgba(155, 69, 255, .04); }
.tab-btn.active {
    background: rgba(155, 69, 255, .1); color: var(--violet-bright);
    border-bottom: 2px solid var(--violet-bright); border-radius: var(--r-md) var(--r-md) 0 0;
}

.tab-content { display: none; animation: fadeIn .3s ease; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ─── SEARCH BAR ─── */
.search-bar { display: flex; gap: 10px; margin-bottom: 16px; flex-wrap: wrap; align-items: center; }
.search-bar input, .search-bar select {
    flex: 1; min-width: 180px; padding: 10px 14px; background: var(--bg);
    border: 1px solid var(--border-2); border-radius: var(--r-md); color: var(--tx);
    font-family: inherit; font-size: .85rem; transition: var(--ease);
}
.search-bar input:focus, .search-bar select:focus {
    border-color: var(--violet-bright); box-shadow: 0 0 0 3px rgba(124, 92, 255, .12); outline: none;
}
.search-bar input::placeholder { color: var(--tx-4); }
.kbd-hint { font-size: .68rem; color: var(--tx-4); padding: 2px 6px; background: var(--bg-2); border: 1px solid var(--border); border-radius: 4px; font-family: var(--font-mono); }

/* ─── TABLE ─── */
.table-container {
    overflow-x: auto; background: var(--bg-1); border: 1px solid var(--border);
    border-radius: var(--r-xl); margin-bottom: 16px; overflow: hidden;
}
.table-container .table-header {
    padding: 16px 20px; border-bottom: 1px solid var(--border);
    display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;
}
.table-container .table-header h3 { font-family: var(--font-display); font-size: 1rem; font-weight: 600; color: var(--tx); }
table { width: 100%; border-collapse: collapse; font-size: .85rem; }
table th, table td { padding: 12px 16px; text-align: left; border-bottom: 1px solid var(--border); vertical-align: middle; }
table th {
    background: var(--bg-2); color: var(--tx-2); font-weight: 700; font-size: .7rem;
    text-transform: uppercase; letter-spacing: .06em; cursor: pointer; user-select: none;
    position: relative; transition: var(--ease);
}
table th:hover { color: var(--tx); background: rgba(155, 69, 255, .05); }
table th .sort-arrow { font-size: .55rem; margin-left: 4px; opacity: .4; }
table th .sort-arrow.active { color: var(--violet-bright); opacity: 1; }
table tr:last-child td { border-bottom: none; }
table tbody tr { transition: background .15s; }
table tbody tr:hover { background: rgba(155, 69, 255, .03); }
table td { color: var(--tx-3); }
table td strong { color: var(--tx-2); font-weight: 600; }

.empty-state { padding: 60px 20px; text-align: center; color: var(--tx-4); }
.empty-state .empty-icon { font-size: 2.5rem; margin-bottom: 12px; opacity: .5; }
.empty-state .empty-title { font-size: 1rem; font-weight: 600; color: var(--tx-3); margin-bottom: 4px; }
.empty-state .empty-desc { font-size: .82rem; color: var(--tx-4); }
.error-state { padding: 40px 20px; text-align: center; color: var(--danger); font-size: .9rem; }

/* ─── SKELETON ─── */
.skeleton-row td { padding: 14px 16px; }
.skeleton-bar {
    height: 12px; border-radius: 4px;
    background: linear-gradient(90deg, rgba(255,255,255,.04), rgba(255,255,255,.09), rgba(255,255,255,.04));
    background-size: 200% 100%; animation: shimmer 1.4s infinite;
}
@keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

/* ─── BADGES ─── */
.badge { display: inline-block; padding: 3px 12px; border-radius: var(--r-pill); font-size: .7rem; font-weight: 700; text-transform: capitalize; }
.badge-free { background: rgba(74, 222, 128, .08); color: var(--success); border: 1px solid rgba(74, 222, 128, .15); }
.badge-pro { background: rgba(155, 69, 255, .08); color: var(--violet-bright); border: 1px solid rgba(155, 69, 255, .15); }
.badge-unlimited { background: linear-gradient(135deg, rgba(251,146,60,.15), rgba(234,179,8,.12)); color: #fbbf24; border: 1px solid rgba(251, 146, 60, .2); }
.badge-pending { background: rgba(255, 109, 46, .08); color: #ff7a3d; border: 1px solid rgba(255, 109, 46, .15); }
.badge-accepted { background: rgba(74, 222, 128, .08); color: var(--success); border: 1px solid rgba(74, 222, 128, .15); }
.badge-rejected { background: rgba(232, 57, 154, .08); color: var(--rose); border: 1px solid rgba(232, 57, 154, .15); }
.badge-banned { background: rgba(232, 57, 154, .12); color: var(--rose); border: 1px solid rgba(232, 57, 154, .2); }
.badge-active { background: rgba(74, 222, 128, .08); color: var(--success); border: 1px solid rgba(74, 222, 128, .15); }
.badge-disabled { background: rgba(255, 255, 255, .04); color: var(--tx-4); border: 1px solid var(--border-2); }

/* ─── COPY EMAIL ─── */
.copy-email {
    cursor: pointer; position: relative; transition: var(--ease);
    display: inline-flex; align-items: center; gap: 4px;
}
.copy-email:hover { color: var(--violet-bright); }
.copy-email::after { content: '📋'; font-size: .65rem; opacity: 0; transition: opacity .2s; }
.copy-email:hover::after { opacity: .6; }
.copy-email.copied::after { content: '✓'; opacity: 1; color: var(--success); }

/* ─── PAGINATION ─── */
.pagination {
    display: flex; justify-content: center; align-items: center; gap: 6px;
    padding: 14px 20px; border-top: 1px solid var(--border);
}
.page-btn {
    min-width: 32px; height: 32px; padding: 0 10px; border-radius: var(--r-sm);
    background: transparent; border: 1px solid var(--border-2); color: var(--tx-3);
    font-size: .78rem; font-weight: 600; cursor: pointer; transition: var(--ease);
    font-family: inherit;
}
.page-btn:hover:not(:disabled) { background: rgba(155, 69, 255, .08); color: var(--violet-bright); border-color: rgba(155, 69, 255, .25); }
.page-btn.active { background: var(--grad-btn); color: #fff; border-color: transparent; }
.page-btn:disabled { opacity: .4; cursor: not-allowed; }
.page-info { font-size: .74rem; color: var(--tx-4); padding: 0 8px; }

/* ─── FEEDBACK CARDS ─── */
.feedback-card {
    background: var(--bg); border: 1px solid var(--border);
    border-radius: var(--r-lg); padding: 16px 20px; margin-bottom: 12px; transition: var(--ease);
}
.feedback-card:hover { border-color: var(--border-2); }
.feedback-card .fb-header { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 6px; }
.feedback-card .fb-header .fb-email { font-weight: 600; color: var(--tx-2); }
.feedback-card .fb-header .fb-date { font-size: .7rem; color: var(--tx-4); }
.feedback-card .fb-comment { color: var(--tx-3); line-height: 1.6; margin: 6px 0 10px; font-size: .88rem; }
.feedback-card .fb-actions { display: flex; gap: 6px; flex-wrap: wrap; }

/* ─── CHART ─── */
.chart-container { position: relative; height: 280px; width: 100%; padding: 8px 4px 0; }
canvas { display: block; width: 100% !important; height: 100% !important; }
.chart-tooltip {
    position: absolute; background: var(--bg-2); border: 1px solid var(--border-2);
    border-radius: var(--r-sm); padding: 6px 10px; font-size: .72rem; color: var(--tx);
    pointer-events: none; opacity: 0; transition: opacity .15s; z-index: 10;
    box-shadow: 0 4px 16px rgba(0, 0, 0, .6); white-space: nowrap;
}
.chart-tooltip.visible { opacity: 1; }

/* ─── CMS FORM ─── */
.cms-form .form-group { margin-bottom: 16px; }
.cms-form .form-group label { display: block; font-size: .76rem; font-weight: 600; color: var(--tx-2); margin-bottom: 4px; }
.cms-form .form-group input, .cms-form .form-group textarea, .cms-form .form-group select {
    width: 100%; padding: 10px 14px; background: var(--bg); border: 1px solid var(--border-2);
    border-radius: var(--r-md); color: var(--tx); font-family: inherit; font-size: .87rem;
    transition: var(--ease); resize: vertical;
}
.cms-form .form-group input:focus, .cms-form .form-group textarea:focus, .cms-form .form-group select:focus {
    border-color: var(--violet-bright); box-shadow: 0 0 0 3px rgba(124, 92, 255, .1); outline: none;
}
.cms-form .form-group textarea { min-height: 80px; }
.cms-divider { height: 1px; background: linear-gradient(90deg, transparent, var(--border) 20%, var(--border) 80%, transparent); margin: 20px 0; }

/* ─── MODAL ─── */
.modal-overlay {
    position: fixed; inset: 0; z-index: 2000; background: rgba(4, 4, 6, .75);
    backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center;
    padding: 20px; opacity: 0; pointer-events: none; transition: opacity .3s ease;
}
.modal-overlay.active { opacity: 1; pointer-events: all; }
.modal-box {
    position: relative; width: 100%; max-width: 560px; max-height: 90vh; overflow-y: auto;
    background: var(--bg-1); border: 1px solid var(--border-2); border-radius: var(--r-2xl);
    padding: 30px 32px; box-shadow: var(--shadow-card), var(--shadow-glow);
    transform: scale(.96) translateY(8px); transition: transform .3s cubic-bezier(.34, 1.56, .64, 1);
}
.modal-overlay.active .modal-box { transform: scale(1) translateY(0); }
.modal-box .modal-close {
    position: absolute; top: 16px; right: 16px; width: 30px; height: 30px;
    border-radius: 50%; background: rgba(255, 255, 255, .04); border: 1px solid var(--border-2);
    color: var(--tx-3); cursor: pointer; display: flex; align-items: center; justify-content: center;
    font-size: .9rem; transition: var(--ease);
}
.modal-box .modal-close:hover { background: rgba(255, 255, 255, .08); color: var(--tx); }
.modal-box .modal-kicker { font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--violet-bright); margin-bottom: 4px; }
.modal-box .modal-title { font-family: var(--font-display); font-size: 1.2rem; font-weight: 600; color: var(--tx); margin-bottom: 16px; letter-spacing: -.01em; }
.modal-box .field { margin-bottom: 14px; }
.modal-box .field label { display: block; font-size: .76rem; font-weight: 600; color: var(--tx-2); margin-bottom: 4px; }
.modal-box .field input, .modal-box .field textarea, .modal-box .field select {
    width: 100%; padding: 10px 14px; background: var(--bg); border: 1px solid var(--border-2);
    border-radius: var(--r-md); color: var(--tx); font-family: inherit; font-size: .87rem; transition: var(--ease);
}
.modal-box .field input:focus, .modal-box .field textarea:focus, .modal-box .field select:focus {
    border-color: var(--violet-bright); box-shadow: 0 0 0 3px rgba(124, 92, 255, .1); outline: none;
}
.modal-box .field textarea { resize: vertical; min-height: 60px; }

/* ─── CONFIRM DIALOG ─── */
.confirm-overlay {
    position: fixed; inset: 0; z-index: 3000; background: rgba(4, 4, 6, .8);
    backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center;
    padding: 20px; opacity: 0; pointer-events: none; transition: opacity .25s;
}
.confirm-overlay.active { opacity: 1; pointer-events: all; }
.confirm-box {
    background: var(--bg-1); border: 1px solid var(--border-2); border-radius: var(--r-xl);
    padding: 28px 26px; max-width: 420px; width: 100%;
    box-shadow: 0 24px 64px rgba(0, 0, 0, .6);
    transform: scale(.96); transition: transform .25s cubic-bezier(.34, 1.56, .64, 1);
}
.confirm-overlay.active .confirm-box { transform: scale(1); }
.confirm-icon { font-size: 2.4rem; margin-bottom: 8px; text-align: center; }
.confirm-title { font-family: var(--font-display); font-size: 1.1rem; font-weight: 600; color: var(--tx); margin-bottom: 8px; text-align: center; }
.confirm-message { font-size: .85rem; color: var(--tx-3); line-height: 1.55; margin-bottom: 20px; text-align: center; }
.confirm-actions { display: flex; gap: 8px; }
.confirm-actions .btn { flex: 1; }

/* ─── TOAST ─── */
.toast-container {
    position: fixed; bottom: 24px; right: 24px; z-index: 4000;
    display: flex; flex-direction: column; gap: 8px; max-width: 400px; width: 100%;
    pointer-events: none;
}
.toast {
    padding: 14px 16px 14px 20px; background: var(--bg-1); backdrop-filter: blur(12px);
    border: 1px solid var(--border-2); border-radius: var(--r-lg);
    border-left: 4px solid var(--violet-bright); box-shadow: var(--shadow-card);
    animation: slideIn .3s ease; font-size: .85rem; color: var(--tx-2);
    display: flex; align-items: center; gap: 10px; position: relative; overflow: hidden;
    pointer-events: all; transition: opacity .3s, transform .3s;
}
.toast.success { border-left-color: var(--success); }
.toast.error { border-left-color: var(--danger); }
.toast.warning { border-left-color: var(--warning); }
.toast.leaving { opacity: 0; transform: translateX(100%); }
.toast .toast-icon { font-size: 1rem; flex-shrink: 0; }
.toast .toast-msg { flex: 1; }
.toast .toast-close { background: none; border: none; color: var(--tx-4); cursor: pointer; font-size: .9rem; padding: 0 4px; }
.toast .toast-close:hover { color: var(--tx-2); }
.toast .toast-progress {
    position: absolute; bottom: 0; left: 0; height: 2px;
    background: var(--grad); animation: toastProgress 4s linear forwards;
}
.toast.success .toast-progress { background: var(--success); }
.toast.error .toast-progress { background: var(--danger); }
.toast.warning .toast-progress { background: var(--warning); }
@keyframes slideIn { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
@keyframes toastProgress { from { width: 100%; } to { width: 0%; } }

/* ─── SYSTEM INFO ─── */
.sys-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.sys-info-item { padding: 12px 16px; background: var(--bg); border: 1px solid var(--border); border-radius: var(--r-md); }
.sys-info-item .sys-label { font-size: .65rem; text-transform: uppercase; letter-spacing: .06em; color: var(--tx-4); font-weight: 700; }
.sys-info-item .sys-value { font-size: .9rem; color: var(--tx-2); font-weight: 600; margin-top: 2px; word-break: break-all; }

.danger-zone { margin-top: 16px; padding: 20px; border: 1px solid rgba(232, 57, 154, .2); border-radius: var(--r-lg); background: rgba(232, 57, 154, .04); }
.danger-zone .dz-title { font-weight: 700; color: var(--rose); margin-bottom: 12px; font-size: .9rem; display: flex; align-items: center; gap: 8px; }
.danger-zone .dz-actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* ─── LOGIN OVERLAY ─── */
.login-overlay {
    position: fixed; inset: 0; z-index: 5000; background: rgba(4, 4, 6, .95);
    backdrop-filter: blur(20px); display: none; align-items: center; justify-content: center;
    padding: 20px; overflow: hidden;
}
.login-overlay::before {
    content: ''; position: absolute; inset: 0;
    background:
        radial-gradient(circle at 20% 30%, rgba(155, 69, 255, .15) 0%, transparent 40%),
        radial-gradient(circle at 80% 70%, rgba(232, 57, 154, .12) 0%, transparent 40%);
    animation: loginBg 12s ease-in-out infinite;
}
@keyframes loginBg {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}
.login-overlay.active { display: flex; }
.login-box {
    position: relative; max-width: 420px; width: 100%;
    background: rgba(11, 12, 16, .9); border: 1px solid var(--border-2);
    border-radius: var(--r-2xl); padding: 40px 32px;
    box-shadow: 0 32px 80px rgba(0, 0, 0, .8), 0 0 0 1px rgba(155, 69, 255, .1);
    text-align: center; backdrop-filter: blur(24px);
    animation: loginBoxIn .6s cubic-bezier(.16, 1, .3, 1);
}
@keyframes loginBoxIn {
    from { opacity: 0; transform: translateY(20px) scale(.96); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}
.login-box .login-icon {
    font-size: 3rem; margin-bottom: 12px;
    display: inline-block; animation: crownFloat 3s ease-in-out infinite;
    filter: drop-shadow(0 0 20px rgba(251, 191, 36, .5));
}
@keyframes crownFloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
.login-box h2 { font-family: var(--font-display); font-size: 1.4rem; font-weight: 700; color: var(--tx); margin-bottom: 8px; }
.login-box p { color: var(--tx-3); font-size: .9rem; margin-bottom: 20px; line-height: 1.6; }
.login-box .field { margin-bottom: 14px; text-align: left; position: relative; }
.login-box .field label { display: block; font-size: .76rem; font-weight: 600; color: var(--tx-2); margin-bottom: 4px; }
.login-box .field input {
    width: 100%; padding: 11px 14px; background: var(--bg); border: 1px solid var(--border-2);
    border-radius: var(--r-md); color: var(--tx); font-family: inherit; font-size: .87rem; transition: var(--ease);
}
.login-box .field input:focus { border-color: var(--violet-bright); box-shadow: 0 0 0 3px rgba(124, 92, 255, .15); outline: none; }
.password-wrap { position: relative; }
.password-wrap input { padding-right: 44px !important; }
.password-toggle {
    position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
    background: none; border: none; color: var(--tx-4); cursor: pointer; padding: 4px;
    font-size: .9rem; line-height: 1;
}
.password-toggle:hover { color: var(--tx-2); }
.login-box .login-error {
    color: var(--danger); font-size: .8rem; margin-bottom: 12px; display: none;
    padding: 8px 12px; background: rgba(248, 113, 113, .08); border: 1px solid rgba(248, 113, 113, .15);
    border-radius: var(--r-sm); text-align: left;
}
.login-box .login-error.show { display: block; animation: shake .4s; }
@keyframes shake {
    0%, 100% { transform: translateX(0); }
    25% { transform: translateX(-4px); }
    75% { transform: translateX(4px); }
}
.login-footer { margin-top: 16px; font-size: .7rem; color: var(--tx-4); }

/* ─── FOOTER ─── */
.footer { padding: 40px 0 20px; border-top: 1px solid var(--border); margin-top: 40px; }
.footer-inner { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 14px; }
.footer-copy { font-size: .76rem; color: var(--tx-4); }
.back-top-btn { background: none; border: 1px solid var(--border-2); border-radius: var(--r-md); padding: 6px 14px; font-size: .76rem; color: var(--tx-3); cursor: pointer; transition: var(--ease); font-family: inherit; }
.back-top-btn:hover { color: var(--tx); border-color: var(--border-violet); }

/* ─── RESPONSIVE ─── */
@media (max-width:1024px) {
    .stats-grid { grid-template-columns: repeat(2, 1fr); }
    .sys-info-grid { grid-template-columns: 1fr; }
}
@media (max-width:820px) {
    body { padding-top: calc(var(--nav-h) + 14px); }
    .main-wrap { padding: 0 18px 40px; }
    .admin-header { flex-direction: column; align-items: stretch; text-align: center; padding: 16px 18px; }
    .admin-header-left { justify-content: center; }
    .admin-stats-bar { justify-content: center; }
    .admin-user { justify-content: center; }
    .stats-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .stat-card { padding: 14px 16px; }
    .stat-card .stat-value { font-size: 1.5rem; }
    .tab-btn { padding: 8px 14px; font-size: .75rem; }
    .modal-box { padding: 20px 18px; }
    .search-bar input { min-width: 120px; }
    .confirm-box { padding: 24px 20px; }
}
@media (max-width:480px) {
    .stats-grid { grid-template-columns: 1fr 1fr; gap: 8px; }
    .stat-card .stat-value { font-size: 1.2rem; }
    .stat-card .stat-label { font-size: .7rem; }
    .admin-title { font-size: 1.1rem; }
    .tab-btn { padding: 6px 10px; font-size: .7rem; }
    .table-container table { font-size: .75rem; }
    table th, table td { padding: 8px 10px; }
    .modal-box { padding: 16px 14px; }
    .login-box { padding: 28px 20px; }
    .footer-inner { flex-direction: column; text-align: center; }
}

scripts.content:
'use strict';

// ─── ENVIRONMENT DETECTION ───
const isLocal = ['localhost', '127.0.0.1'].includes(window.location.hostname);
const BASE_URL = isLocal
    ? 'http://127.0.0.1:8000'
    : 'https://mohammadtalhaa-free-voice-labs-backend.hf.space';

const SESSION_KEY = "fvl_session";
const ADMIN_EMAIL = "talha@vfl.ai";
const PAGE_SIZE = 20;

// ─── STATE ───
let allUsers = [];
let allFeedback = [];
let allVoices = [];
let allBlends = [];
let generationHistory = [];
let statsInterval = null;
let activeTab = 'users';
let isAuthenticated = false;
let userPage = 1;
let userSortKey = null;
let userSortDir = 'asc';

// ─── SESSION ───
const getSession = () => { try { const r = sessionStorage.getItem(SESSION_KEY); return r ? JSON.parse(r) : null; } catch { return null; } };
const setSession = d => { try { sessionStorage.setItem(SESSION_KEY, JSON.stringify(d)); } catch {} };
const clearSession = () => { try { sessionStorage.removeItem(SESSION_KEY); } catch {} };

function checkAuth() {
    const session = getSession();
    if (session && session.email === ADMIN_EMAIL) { isAuthenticated = true; return session; }
    isAuthenticated = false;
    return null;
}

// ─── DEBOUNCE ───
const debounce = (fn, ms = 300) => {
    let t;
    return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
};

// ─── CUSTOM CONFIRM ───
let confirmResolve = null;
function customConfirm(title, message, confirmLabel = 'Confirm', danger = true) {
    return new Promise(resolve => {
        confirmResolve = resolve;
        document.getElementById('confirm-title').textContent = title;
        document.getElementById('confirm-message').textContent = message;
        const okBtn = document.getElementById('confirm-ok');
        okBtn.textContent = confirmLabel;
        okBtn.className = danger ? 'btn btn-danger' : 'btn btn-primary';
        document.getElementById('confirm-icon').textContent = danger ? '⚠️' : '❓';
        document.getElementById('confirm-overlay').classList.add('active');
    });
}
function closeConfirm(result) {
    document.getElementById('confirm-overlay').classList.remove('active');
    if (confirmResolve) { confirmResolve(result); confirmResolve = null; }
}

// ─── TOAST ───
function showToast(message, type = 'success', duration = 4000) {
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');
    const icons = { success: '✓', error: '✕', warning: '⚠' };
    toast.className = `toast ${type}`;
    toast.innerHTML = `
        <span class="toast-icon">${icons[type] || '◆'}</span>
        <span class="toast-msg">${message}</span>
        <button class="toast-close" aria-label="Dismiss">✕</button>
        <div class="toast-progress" style="animation-duration:${duration}ms"></div>
    `;
    const close = () => { toast.classList.add('leaving'); setTimeout(() => toast.remove(), 300); };
    toast.querySelector('.toast-close').onclick = close;
    container.appendChild(toast);
    setTimeout(close, duration);
}

// ─── LOGIN ───
async function handleAdminLogin() {
    const email = document.getElementById('login-email').value.trim().toLowerCase();
    const password = document.getElementById('login-password').value;
    const errorEl = document.getElementById('login-error');
    const submitBtn = document.getElementById('login-submit');

    if (!email || !password) {
        errorEl.textContent = 'Please enter both email and password.';
        errorEl.classList.add('show');
        return;
    }

    submitBtn.disabled = true;
    submitBtn.innerHTML = '<span class="spinner"></span> Signing in...';
    errorEl.classList.remove('show');

    try {
        const res = await fetch(`${BASE_URL}/api/auth/login`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email, password })
        });
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || err.message || 'Login failed');
        }
        const data = await res.json();
        if (data.email !== ADMIN_EMAIL) throw new Error('Access denied. Admin only.');

        setSession({ email: data.email, token: data.token, plan: data.plan });
        isAuthenticated = true;
        document.getElementById('login-overlay').classList.remove('active');
        renderNavAuth();
        renderMobileNav();
        await loadDashboard();
        showToast('Welcome back, Admin! 👑', 'success');
    } catch (e) {
        errorEl.textContent = e.message;
        errorEl.classList.add('show');
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Sign In';
    }
}

// ─── LOGOUT (FIXED: redirects to home) ───
function handleLogout() {
    clearSession();
    isAuthenticated = false;
    if (statsInterval) clearInterval(statsInterval);
    // Redirect to home page instead of showing login overlay
    window.location.href = '/';
}

// ─── NAV ───
function renderNavAuth() {
    const container = document.getElementById("island-right");
    if (!container) return;
    const s = getSession();
    if (s?.email) {
        const initials = s.email.substring(0, 2).toUpperCase();
        container.innerHTML = `<span style="font-size:.72rem;color:var(--tx-2);padding:0 8px;">👑 Admin</span><button class="island-btn island-btn-ghost island-btn-sm" onclick="handleLogout()">Sign Out</button>`;
    } else {
        container.innerHTML = `<button class="island-btn island-btn-primary island-btn-sm" onclick="openSignInModal()">Sign In</button>`;
    }
}

function renderMobileNav() {
    const overlay = document.getElementById("island-mobile-overlay");
    if (!overlay) return;
    const s = getSession();
    overlay.innerHTML = `
        <a href="/#studio" class="mob-link"><span class="mob-icon">🧠</span> Studio</a>
        <a href="/#pricing" class="mob-link"><span class="mob-icon">💎</span> Pricing</a>
        <a href="/#platform" class="mob-link"><span class="mob-icon">⚙️</span> Platform</a>
        <div class="mob-divider"></div>
        ${s?.email ? `
            <div style="padding:8px 16px;font-size:.78rem;color:var(--tx-3);">Signed in as <strong style="color:var(--tx-2);">${s.email}</strong></div>
