function sortUsers(key) {
    if (userSortKey === key) { userSortDir = userSortDir === 'asc' ? 'desc' : 'asc'; }
    else { userSortKey = key; userSortDir = 'asc'; }
    renderUsersTable();
}

function renderUsersTable() {
    const search = document.getElementById('user-search')?.value.toLowerCase() || '';
    let filtered = allUsers.filter(u => u.email.toLowerCase().includes(search));
    if (userSortKey) {
        filtered.sort((a, b) => {
            let av = a[userSortKey], bv = b[userSortKey];
            if (typeof av === 'string') av = av.toLowerCase();
            if (typeof bv === 'string') bv = bv.toLowerCase();
            if (av == null) av = '';
            if (bv == null) bv = '';
            if (av < bv) return userSortDir === 'asc' ? -1 : 1;
            if (av > bv) return userSortDir === 'asc' ? 1 : -1;
            return 0;
        });
    }
    // Update sort indicators
    ['email','plan','banned','created_at','generations'].forEach(k => {
        const el = document.getElementById(`sort-${k}`);
        if (el) {
            el.textContent = userSortKey === k ? (userSortDir === 'asc' ? '▲' : '▼') : '';
            el.className = 'sort-arrow' + (userSortKey === k ? ' active' : '');
        }
    });

    const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
    if (userPage > totalPages) userPage = totalPages;
    const paginated = filtered.slice((userPage - 1) * PAGE_SIZE, userPage * PAGE_SIZE);

    const tbody = document.getElementById('users-table-body');
    if (!paginated.length) {
        tbody.innerHTML = `<tr><td colspan="6"><div class="empty-state"><div class="empty-icon">👤</div><div class="empty-title">No users found</div><div class="empty-desc">Try a different search term</div></div></td></tr>`;
        document.getElementById('users-pagination').innerHTML = '';
        return;
    }
    tbody.innerHTML = paginated.map(u => `
        <tr>
            <td><strong class="copy-email" onclick="copyEmail('${escapeHtml(u.email)}')">${escapeHtml(u.email)}</strong></td>
            <td><span class="badge badge-${u.plan}">${u.plan}</span></td>
            <td><span class="badge ${u.banned ? 'badge-banned' : 'badge-active'}">${u.banned ? 'Banned' : 'Active'}</span></td>
            <td>${u.created_at || '—'}</td>
            <td>${u.generations || 0}</td>
            <td style="white-space:nowrap;">
                <button class="btn btn-primary btn-sm" onclick="editUser('${escapeHtml(u.email)}')" title="Edit">✏️</button>
                <button class="btn btn-warning btn-sm" onclick="toggleBanUser('${escapeHtml(u.email)}', ${!u.banned})" title="${u.banned ? 'Unban' : 'Ban'}">${u.banned ? '🔓' : '🔨'}</button>
                <button class="btn btn-danger btn-sm" onclick="deleteUser('${escapeHtml(u.email)}')" title="Delete">🗑️</button>
            </td>
        </tr>
    `).join('');

    // Pagination
    const pag = document.getElementById('users-pagination');
    pag.innerHTML = '';
    if (totalPages > 1) {
        pag.innerHTML += `<button class="page-btn" ${userPage === 1 ? 'disabled' : ''} onclick="goToPage(${userPage - 1})">←</button>`;
        for (let i = 1; i <= totalPages; i++) {
            if (i === 1 || i === totalPages || Math.abs(i - userPage) <= 1) {
                pag.innerHTML += `<button class="page-btn ${i === userPage ? 'active' : ''}" onclick="goToPage(${i})">${i}</button>`;
            } else if (i === userPage - 2 || i === userPage + 2) {
                pag.innerHTML += `<span class="page-info">…</span>`;
            }
        }
        pag.innerHTML += `<button class="page-btn" ${userPage === totalPages ? 'disabled' : ''} onclick="goToPage(${userPage + 1})">→</button>`;
    }
}

