function drawChart() {
    const canvas = document.getElementById('generations-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.parentElement.getBoundingClientRect();
    const width = rect.width || 600;
    const height = 260;
    canvas.width = width * 2; canvas.height = height * 2;
    canvas.style.width = width + 'px'; canvas.style.height = height + 'px';
    ctx.scale(2, 2);

    const data = generationHistory.length ? generationHistory : [{ date: 'No data', count: 0 }];
    const labels = data.map(d => d.date);
    const values = data.map(d => d.count);
    const padding = { top: 20, right: 20, bottom: 30, left: 40 };
    const cw = width - padding.left - padding.right;
    const ch = height - padding.top - padding.bottom;
    const maxVal = Math.max(...values, 1);
    const step = maxVal / 5;
    ctx.clearRect(0, 0, width, height);

    // Grid
    ctx.strokeStyle = 'rgba(155,69,255,0.15)';
    ctx.lineWidth = 1;
    ctx.fillStyle = '#7a6898';
    ctx.font = '10px "Plus Jakarta Sans", sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
        const y = padding.top + ch - (i / 5) * ch;
        ctx.beginPath(); ctx.moveTo(padding.left, y); ctx.lineTo(width - padding.right, y); ctx.stroke();
        ctx.fillText(Math.round(i * step), padding.left - 5, y + 4);
    }

    // Bars
    const barWidth = Math.min(20, cw / values.length * 0.6);
    const gap = cw / values.length;
    values.forEach((val, i) => {
        const x = padding.left + i * gap + (gap - barWidth) / 2;
        const barHeight = (val / maxVal) * ch;
        const y = padding.top + ch - barHeight;
        const grad = ctx.createLinearGradient(x, y, x, padding.top + ch);
        grad.addColorStop(0, '#bf76ff'); grad.addColorStop(1, '#e8399a');
        ctx.fillStyle = grad;
        ctx.fillRect(x, y, barWidth, barHeight);
        if (labels[i]) {
            ctx.fillStyle = '#7a6898';
            ctx.textAlign = 'center';
            ctx.font = '9px "Plus Jakarta Sans", sans-serif';
            ctx.fillText(labels[i].slice(5), x + barWidth / 2, padding.top + ch + 16);
        }
        if (val > 0) {
            ctx.fillStyle = '#f2ebff';
            ctx.textAlign = 'center';
            ctx.font = '9px "Plus Jakarta Sans", sans-serif';
            ctx.fillText(val, x + barWidth / 2, y - 5);
        }
    });

    // Store data for tooltip
    canvas._chartData = { data, padding, cw, ch, gap, width, height };
}

// Chart tooltip
document.getElementById('generations-chart')?.addEventListener('mousemove', (e) => {
    const canvas = e.target;
    const info = canvas._chartData;
    if (!info) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const idx = Math.floor((x - info.padding.left) / info.gap);
    const tip = document.getElementById('chart-tooltip');
    if (idx >= 0 && idx < info.data.length) {
        const d = info.data[idx];
        tip.textContent = `${d.date} — ${d.count} generations`;
        tip.style.left = (x + 10) + 'px';
        tip.style.top = (e.clientY - rect.top - 30) + 'px';
        tip.classList.add('visible');
    } else { tip.classList.remove('visible'); }
});
document.getElementById('generations-chart')?.addEventListener('mouseleave', () => {
    document.getElementById('chart-tooltip')?.classList.remove('visible');
});

