async function loadCMSSettings() {
    try {
        const data = await adminFetch('/api/cms');
        document.getElementById('cms-hero-title').value = data.hero_title || 'Free Voice Labs';
        document.getElementById('cms-hero-subtitle').value = data.hero_subtitle || '';
        document.getElementById('cms-announcement').value = data.announcement || '';
        document.getElementById('cms-pro-price').value = data.pricing_pro_price || '4.99';
        document.getElementById('cms-unlimited-price').value = data.pricing_unlimited_price || '29.99';
    } catch (e) { console.error('CMS error:', e); }
}

async function saveCMSSettings() {
    const btn = document.getElementById('cms-save-btn');
    btn.disabled = true; btn.innerHTML = '<span class="spinner"></span> Saving...';
    try {
        await adminFetch('/api/cms', {
            method: 'POST',
            body: JSON.stringify({
                hero_title: document.getElementById('cms-hero-title').value,
                hero_subtitle: document.getElementById('cms-hero-subtitle').value,
                announcement: document.getElementById('cms-announcement').value,
                pricing_pro_price: document.getElementById('cms-pro-price').value,
                pricing_unlimited_price: document.getElementById('cms-unlimited-price').value,
                maintenance_mode: false
            })
        });
        showToast('CMS settings saved!', 'success');
    } catch (e) { showToast('Error: ' + e.message, 'error'); }
    finally { btn.disabled = false; btn.textContent = '💾 Save All Settings'; }
}

