async function clearAllData() {
    const ok = await customConfirm('NUKE EVERYTHING', 'This will delete all feedback, CMS, and user records (except admin). Type-confirm required.', 'NUKE', true);
    if (!ok) return;
    const typed = prompt('Type "NUKE" to confirm');
