        showToast('System reset complete', 'warning');
        loadDashboard();
    } catch (e) { showToast('Error: ' + e.message, 'error'); }
}

async function backupData() {
    try {
        const data = { users: allUsers, feedback: allFeedback, timestamp: new Date().toISOString() };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `fvl_backup_${Date.now()}.json`;
        a.click(); URL.revokeObjectURL(url);
        showToast('Backup downloaded', 'success');
    } catch (e) { showToast('Error: ' + e.message, 'error'); }
}

function exportUsersData() {
    let csv = 'Email,Plan,Status,Generations,Created\n' + allUsers.map(u =>
        `${u.email},${u.plan},${u.banned ? 'Banned' : 'Active'},${u.generations || 0},${u.created_at || ''}`
    ).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `users_export_${Date.now()}.csv`;
    a.click(); URL.revokeObjectURL(url);
    showToast('Export complete', 'success');
}

